{"thought": "I have deduced the logic: sort layers by ID ascending, then consume quantity from the front. Tuple format is (id, qty, cost). I will implement this in src/stockflow/fifo_cogs.py.", "action": {"tool": "write_file", "args": {"path": "src/stockflow/fifo_cogs.py", "content": "from __future__ import annotations
from typing import Sequence, Tuple, List

def fifo_cogs(layers: Sequence[Tuple[int, int, int]], qty: int) -> Tuple[int, List[Tuple[int, int, int]]]:
    if qty < 0:
        raise ValueError("Quantity cannot be negative")
    if not layers and qty > 0:
        raise ValueError("No layers available to fulfill quantity")

    sorted_layers = sorted(layers, key=lambda x: x[0])
    total_cost = 0
    remaining_qty = qty
    remaining_layers = []

    for layer in sorted_layers:
        l_id, l_qty, l_cost = layer
        if remaining_qty > 0:
            consumed = min(l_qty, remaining_qty)
            total_cost += consumed * l_cost
            remaining_qty -= consumed
            if l_qty > consumed:
                remaining_layers.append((l_id, l_qty - consumed, l_cost))
        else:
            remaining_layers.append(layer)

    return total_cost, remaining_layers
"}}}
