{
  "thought": "I will implement the `dead_stock` function. I'll iterate through the lines once to track the last shipment date for each SKU and filter lines up to `today`. Then I'll use `on_hand_by_location` to determine the total stock on hand. SKUs with positive stock and no shipments within the `idle_days` window (or no shipments at all) will be returned as dead stock.",
  "action": {
    "tool": "write_file",
    "args": {
      "path": "src/stockflow/dead_stock.py",
      "content": "from __future__ import annotations

from typing import Dict, Iterable, List, Mapping
from src.stockflow.parse_movement_line import parse_movement_line
from src.stockflow.on_hand_by_location import on_hand_by_location


def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    """
    List SKUs whose stock has not moved out for a long time (dead stock).

    A SKU is dead stock when its total on-hand (summed over all locations with
    on_hand_by_location, counting movements up to and including `today`) is
    positive and its most recent shipment (SHP) is at least `idle_days` days old,
    i.e. today - last_ship_day >= idle_days. Movements dated after `today` are
    ignored. Blank lines and "#" comment lines are skipped.

    Args:
        lines: movement records; any iterable (it is only iterated once).
        case_sizes: passed through to the parsers.
        today: current day index.
        idle_days: threshold in days, >= 1.

    Returns:
        Sorted list of canonical SKUs.

    Raises:
        ValueError: if idle_days < 1, or for malformed records.
    """
    if idle_days < 1:
        raise ValueError("idle_days must be >= 1")

    filtered_lines = []
    sku_last_ship: Dict[str, int] = {}

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue

        record = parse_movement_line(line, case_sizes)
        if record['day'] > today:
            continue

        filtered_lines.append(line)
        if record['type'] == 'SHP':
            sku = record['sku']
            day = record['day']
            if day > sku_last_ship.get(sku, -1):
                sku_last_ship[sku] = day

    location_stocks = on_hand_by_location(filtered_lines, case_sizes)
    total_on_hand: Dict[str, int] = {}
    for loc_stock in location_stocks.values():
        for sku, qty in loc_stock.items():
            total_on_hand[sku] = total_on_hand.get(sku, 0) + qty

    dead = []
    for sku, qty in total_on_hand.items():
        if qty > 0:
            # If never shipped, it is considered dead if it has positive stock
            # since today - (-infinity) is always >= idle_days.
            last_ship_day = sku_last_ship.get(sku, float('-inf'))
            if today - last_ship_day >= idle_days:
                dead.append(sku)

    return sorted(dead)"
    }
  }
}
```

